// Float to Integral: Truncation towards zero
float f = 3.99f;
int i_trunc = static_cast<int>(f);      // 3
f = -3.99f;
i_trunc = static_cast<int>(f);      // -3

// Integral to Float: Potential loss of precision
long long large_int = 9007199254740993LL; // > 2^53
double d = large_int;
long long back = static_cast<long long>(d); // Not equal due to precision loss

// Conversion outside target range (Undefined/Implementation-defined)
float big_f = 1e30f;
int overflow_i = static_cast<int>(big_f); // Behavior depends on platform

// Conversion to bool
int zero = 0;
bool b1 = static_cast<bool>(zero);  // false
double non_zero = -5.0;
bool b2 = static_cast<bool>(non_zero); // true
